func (a *BacktrackPanLinkInfo) FilterDuplicateBuildInfo(inputFile string) (int, error) {
	duplicateCount := 0
	start := time.Now()

	// 使用分片map减少内存占用
	const numShards = 256
	hashSets := make([]map[uint64]struct{}, numShards)
	for i := range hashSets {
		hashSets[i] = make(map[uint64]struct{})
	}

	// 分片函数
	getShard := func(hash uint64) int {
		return int(hash) & (numShards - 1)
	}

	// 创建临时文件用于写入去重结果
	tmpFile := inputFile + ".tmp"
	tmpFileHandler, err := os.Create(tmpFile)
	if err != nil {
		return duplicateCount, err
	}
	defer tmpFileHandler.Close()

	writer := bufio.NewWriter(tmpFileHandler)
	defer writer.Flush()

	// 读取输入文件
	inputFileHandler, err := os.Open(inputFile)
	if err != nil {
		return duplicateCount, err
	}
	defer inputFileHandler.Close()

	scanner := bufio.NewScanner(inputFileHandler)
	buf := make([]byte, 0, 64*1024)
	scanner.Buffer(buf, 10*1024*1024)

	var buildInfoExportdata BuildInfoExportdata
	lineCount := 0
	totalCount := 0

	for scanner.Scan() {
		lineCount++
		line := scanner.Bytes()
		if err := sonic.Unmarshal(line, &buildInfoExportdata); err != nil {
			fmt.Printf("文件解析错误@行%d: %v\n", lineCount, err)
			continue
		}
		hash := hashLine([]byte(buildInfoExportdata.Short))
		shard := getShard(hash)

		// 如果哈希已存在，说明是重复行
		if _, exists := hashSets[shard][hash]; exists {
			duplicateCount++
		} else {
			// 新行，添加到集合并写入输出文件
			hashSets[shard][hash] = struct{}{}
			if _, err := writer.Write([]byte(panLinkInfoExportdata.ShortUrl)); err != nil {
				return duplicateCount, err
			}
			if err := writer.WriteByte('\n'); err != nil {
				return duplicateCount, err
			}
			totalCount++
		}

		if lineCount%1000000 == 0 {
			fmt.Printf("已处理 %d 行，去重后 %d 行，发现重复行 %d\n", lineCount, totalCount, duplicateCount)
		}
	}

	if err := scanner.Err(); err != nil {
		return duplicateCount, err
	}

	// 确保写入完成
	if err := writer.Flush(); err != nil {
		return duplicateCount, err
	}
	if err := tmpFileHandler.Close(); err != nil {
		return duplicateCount, err
	}

	// 备份原始文件
	backupFile := inputFile + ".bak"
	if err := os.Rename(inputFile, backupFile); err != nil {
		return duplicateCount, fmt.Errorf("备份原文件失败: %v", err)
	}

	// 用去重后的文件替换原文件
	if err := os.Rename(tmpFile, inputFile); err != nil {
		// 如果重命名失败，尝试恢复备份文件
		if restoreErr := os.Rename(backupFile, inputFile); restoreErr != nil {
			fmt.Printf("严重错误：无法恢复原文件，数据可能丢失: %v\n", restoreErr)
		}
		return duplicateCount, fmt.Errorf("覆盖原文件失败: %v", err)
	}

	// 成功后删除备份文件
	if err := os.Remove(backupFile); err != nil {
		fmt.Printf("警告：删除备份文件失败: %v\n", err)
	}

	fmt.Printf("去重完成！输入文件共 %d 行，去重后 %d 行，重复行数 %d，耗时: %v\n", 
		lineCount, totalCount, duplicateCount, time.Since(start))
	return duplicateCount, nil
}```
